begin;
set local search_path=public,extensions;
select no_plan();
create temporary table delivery_fixture(schedule uuid,notification uuid);
insert into delivery_fixture values(gen_random_uuid(),gen_random_uuid());
grant select on delivery_fixture to authenticated,service_role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.save_report_schedule((select schedule from delivery_fixture),null,array['reports@example.invalid'],true)$$,'P0001','Report schedule permission required','Manager cannot schedule global reports');
select lives_ok($$select public.save_report_schedule((select schedule from delivery_fixture),'10000000-0000-4000-8000-000000000001',array['reports@example.invalid'],true)$$,'Manager can schedule own cooperative summaries');
select ok(not has_function_privilege('authenticated','public.claim_monthly_reports()','execute'),'Browser cannot claim privileged report jobs');
select ok(not has_function_privilege('authenticated','public.claim_alert_deliveries()','execute'),'Browser cannot read external delivery destinations');
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select lives_ok($$select public.set_notification_preference('sms','+96170000000',true)$$,'Recipient explicitly opts in');
reset role;
insert into public.notification(id,cooperative_id,user_id,kind,payload) select notification,'10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','critical_deviation','{}' from delivery_fixture;
select is((select count(*)::integer from public.alert_delivery where notification_id=(select notification from delivery_fixture)),1,'Critical alert queues only the opted-in recipient');
set local role service_role;
select is((select count(*)::integer from public.claim_monthly_reports()),1,'Scheduler claims a prior-month report once');
select is((select count(*)::integer from public.claim_monthly_reports()),0,'Concurrent or immediate repeat scheduler does not claim the same report');
select is((select count(*)::integer from public.claim_alert_deliveries()),1,'Scheduler claims consented critical alert');
select is((select count(*)::integer from public.claim_alert_deliveries()),0,'Delivery lease prevents duplicate concurrent claim');
select * from finish();rollback;
